    local count = table.count(membersIdList)
    for i = 1, count, 1 do
        local go = nil
        local tf = self.controller.gameObject.transform:Find("CardHead"..i)
        if isNull(tf) then
            go = KTool.Instantiate(self.controller.gameObject, self.HomelandInforHeadNode.gameObject)
            go.name = "CardHead"..i
        else
            go = tf.gameObject
        end
        KTool.SetActive(go, true)
        local lb = GetLuaBehaviour(go, CardHeadLuaPath)
        if isNotNull(lb) then
            lb.Env:Refresh(groupId, membersIdList[i])
        end
    end
